# =============================================================================
# 7_Plots_Results_Final.R
# Main Results section: key figures + printed statistics
#
# Data source: Figures/Simulations_Results.csv (unified CSV with three row types:
#   optimized schedules [ID=1..N], ASPB real schedules [ID="ASPB"], and untreated
#   baseline [ID="Untreated"]). Generated by 7_Crear_Df_Resultados_R.py.
#
# Figures produced:
#   Fig 1. Scissor plot: dual-axis visits/risk + cost decomposition
#   Fig 2. Combined heatmap: ΔVisits + risk reduction vs ASPB
#   Fig 3. Lollipop: predictors of untreated risk, allocation, and risk reduction
#
# Printed statistics:
#   - Schedule variable analysis (periodicity vs start day)
#   - Spearman correlations with Zone_INT_Untreated and Frac_Risk
#
# Supplementary figures are in 7_Plots_Results_Final_Supplementary.R
# =============================================================================

rm(list = ls())

library(dplyr)
library(ggplot2)
library(tidyverse)
library(patchwork)

Sys.setlocale("LC_TIME", "C")


# =============================================================================
# PARAMETERS
# =============================================================================

SAVE_PLOTS <- FALSE
SEASON_DAYS <- 244     # April 1 to Nov 30 (always 244 days)

alpha_min  <- 0.1      # minimal scenario (fewest visits, risk just below ASPB)
alpha_best <- 0.5      # efficient scenario (lowest cost)
alpha_even <- 0.8      # intensive scenario (more risk reduction)

# Value-range filter: keep sims with score <= score_min + RANGE_FRAC * (score_max - score_min).
# Draws are automatic: ties → range = 0 → threshold = score_min → all pass.
RANGE_FRAC <- 0.15
MIN_K <- 3

script_dir <- "."
save_dir <- file.path(script_dir, "Figures/Optimization/Final")
temp_dir <- tempdir()
dir.create(save_dir, showWarnings = FALSE, recursive = TRUE)

# Zone short names for compact display — matches manuscript convention
zone_short <- c(
  "Jardins Mossèn Cinto Verdaguer"       = "Cinto Verdaguer",
  "Jardins de Vil\u00b7la Amèlia - Cecília"   = "Vil\u00b7la Am\u00e8lia",
  "Jardins del Teatre Grec"              = "Teatre Grec",
  "Jardins del Turó del Putxet"          = "Tur\u00f3 Putxet",
  "Parc de la Ciutadella"                = "Ciutadella",
  "Parc de la Guineueta"                 = "Guineueta",
  "Parc del Turó de la Peira"            = "Tur\u00f3 Peira"
)

# Zone colors — canonical palette matching 4_Validation_plots.py
zone_colors <- c(
  "Ciutadella"      = "#FDB462",
  "Tur\u00f3 Peira"      = "#FCCDE5",
  "Cinto Verdaguer" = "#80B1D3",
  "Teatre Grec"     = "#BEBADA",
  "Tur\u00f3 Putxet"     = "#FB8072",
  "Vil\u00b7la Am\u00e8lia"   = "#8DD3C7",
  "Guineueta"       = "#B3DE69"
)
 

# =============================================================================
# HELPER: Save and display
# =============================================================================

save_and_display <- function(p, filename, w = 10, h = 8) {
  temp_path <- file.path(temp_dir, filename)
  save_path <- file.path(save_dir, filename)

  dev <- if (grepl("\\.pdf$", filename)) cairo_pdf else NULL

  ggsave(temp_path, plot = p, width = w, height = h, dpi = 300, bg = "white", device = dev)
  system2("xdg-open", temp_path, wait = FALSE)
  Sys.sleep(0.5)

  if (SAVE_PLOTS) {
    ggsave(save_path, plot = p, width = w, height = h, dpi = 300, bg = "white", device = dev)
  }
}


# =============================================================================
# 1. LOAD & FILTER DATA
# =============================================================================

cat("\n========================================\n")
cat("1. LOADING AND FILTERING DATA\n")
cat("========================================\n\n")

all_data <- read.csv(file.path(script_dir, "Figures/Simulations_Results.csv"))
all_data <- all_data %>% mutate(Beta = as.numeric(Beta) / 10)

# Periodicity is JSON for ASPB rows -> whole column reads as character.
# Convert to numeric (ASPB JSON arrays and Untreated NAs become NA, which is fine).
all_data <- all_data %>% mutate(Periodicity = as.numeric(Periodicity))

# Split into three groups: optimized, ASPB, and Untreated
Results <- all_data %>% filter(!ID %in% c("ASPB", "Untreated"))
ASPB_simulations <- all_data %>% filter(ID == "ASPB")
Untreated_simulations <- all_data %>% filter(ID == "Untreated")
rm(all_data)

# Keep simulations within RANGE_FRAC of the best score (J, or INT for beta=0).
# threshold = score_min + RANGE_FRAC * (score_max - score_min)
# Draws are handled automatically: if all sims tie, range = 0 → threshold =
# score_min → all pass score <= threshold. 
top_sims <- Results %>%
  group_by(Year, Beta, ID) %>%
  summarise(J = first(J), INT = sum(INT), .groups = "drop") %>%
  group_by(Year, Beta) %>%
  mutate(
    score = if_else(Beta == 0.0, INT, J),
    threshold = min(score) + RANGE_FRAC * (max(score) - min(score)),
    in_range = score <= threshold,
    # If range keeps fewer than MIN_K, fall back to rank
    rank_score = row_number(score),
    keep = ifelse(rep(sum(in_range) >= MIN_K, n()), in_range, rank_score <= MIN_K)
  ) %>%
  filter(keep) %>%
  ungroup() %>%
  select(Year, Beta, ID)

Results <- Results %>% semi_join(top_sims, by = c("Year", "Beta", "ID"))

cat(sprintf("Optimized rows: %d | ASPB rows: %d | Untreated rows: %d\n",
            nrow(Results), nrow(ASPB_simulations), nrow(Untreated_simulations)))
cat(sprintf("Beta values: %s\n", paste(sort(unique(Results$Beta)), collapse = ", ")))

# Summarise surviving IDs: overall range (min/max) across all alpha-zone-year cells
id_counts <- Results %>%
  distinct(Year, Beta, Zone, ID) %>%
  group_by(Beta, Zone, Year) %>%
  summarise(n_IDs = n_distinct(ID), .groups = "drop")

cat(sprintf("IDs surviving filter: %d – %d per (alpha, zone, year) cell (median = %.0f)\n",
            min(id_counts$n_IDs), max(id_counts$n_IDs), median(id_counts$n_IDs)))

# Build untreated lookup table (Zone_INT_Untreated per zone per year)
untreated_peryear <- Untreated_simulations %>%
  select(Zone, Year, Zone_INT) %>%
  rename(Zone_INT_Untreated = Zone_INT)


# =============================================================================
# COMPUTE VISITS/MONTH (used in multiple sections)
# =============================================================================
# PER = total zone-visits across all 7 zones for a simulation.
# Rate = (PER / N_ZONES / SEASON_DAYS) * 30 = visits per zone per 30-day month,
# scaled to the MOSQUITO SEASON (244 days), not the calendar year.
# This is consistent across optimized and ASPB: both use the same denominator.
# Expressing per calendar-year month would dilute the rate with 7 winter months
# where no treatments happen, which would be misleading.

N_ZONES <- 7
cat("Computing visits/zone/month...\n")

Results_unique <- Results %>%
  distinct(ID, Year, Beta, PER, INT, Norm_INT) %>%
  mutate(Visits_month = (PER / N_ZONES / SEASON_DAYS) * 30,
         Risk_zone_month = (INT / N_ZONES / SEASON_DAYS) * 30)

ASPB_unique <- ASPB_simulations %>%
  distinct(Year, PER, INT, Norm_INT) %>%
  mutate(Visits_month = (PER / N_ZONES / SEASON_DAYS) * 30,
         Risk_zone_month = (INT / N_ZONES / SEASON_DAYS) * 30)

cat(sprintf("Unique optimized sims: %d | ASPB years: %d\n",
            nrow(Results_unique), nrow(ASPB_unique)))


# =============================================================================
# PREDICTOR VARIABLES (precomputed in Python, zone × year level)
# =============================================================================
# All predictor variables were computed in 7_Crear_Df_Resultados_R.py using the
# exact same data loading and interpolation pipeline as the simulation model.

cat("\n========================================\n")
cat("LOADING PREDICTOR VARIABLES\n")
cat("========================================\n\n")

predictors <- read.csv(file.path(script_dir, "Figures/Predictors.csv"),
                       stringsAsFactors = FALSE)

cat(sprintf("Loaded %d rows (zone × year) from Predictors.csv\n", nrow(predictors)))
cat(sprintf("Zones: %d | Years: %s\n",
            length(unique(predictors$Zone)),
            paste(sort(unique(predictors$Year)), collapse = ", ")))
cat("\n")


# =============================================================================
# 2. FIGURE 1: Dual-axis — visits/zone/month (green) + Norm_INT (blue)
# =============================================================================

cat("\n========================================\n")
cat("2. FIGURE 1: DUAL-AXIS (VISITS + RISK)\n")
cat("========================================\n\n")

# x-axis levels
beta_levels <- as.character(sort(unique(Results$Beta)))
x_levels <- c(beta_levels, "ASPB")

# Prepare combined data: visits/zone/month AND Norm_INT per simulation
box_opt <- Results_unique %>% mutate(x_value = as.character(Beta))
box_aspb <- ASPB_unique %>% mutate(x_value = "ASPB")
box_data <- bind_rows(box_opt, box_aspb) %>%
  mutate(x_value = factor(x_value, levels = x_levels))

# Scale factor for dual axis: map Risk_zone_month range onto Visits_month range
vpm_max <- max(box_data$Visits_month, na.rm = TRUE) * 1.1
rzm_max <- max(box_data$Risk_zone_month, na.rm = TRUE) * 1.1
scale_factor <- vpm_max / rzm_max

# Vertical separator position: midpoint between last alpha ("1") and "ASPB"
# In discrete scale, positions are 1, 2, ..., N. ASPB is at position 12.
sep_x <- length(beta_levels) + 0.5   # 11.5

p_fig1 <- ggplot(box_data, aes(x = x_value)) +
  # Vertical separator between alpha values and ASPB
  geom_vline(xintercept = sep_x, linetype = "dotted", color = "grey60",
             linewidth = 0.5) +
  # Green jitter: visits/zone/month (left axis)
  geom_jitter(aes(y = Visits_month), width = 0.2, alpha = 0.4, size = 2,
              color = "#00BA38") +
  stat_summary(aes(y = Visits_month), fun = median, geom = "point",
               shape = 95, size = 12, color = "darkgreen", stroke = 2) +
  # Blue jitter: infested drains / zone / month (right axis)
  geom_jitter(aes(y = Risk_zone_month * scale_factor), width = 0.2, alpha = 0.35,
              size = 2, color = "#619CFF") +
  stat_summary(aes(y = Risk_zone_month * scale_factor), fun = median, geom = "point",
               shape = 95, size = 12, color = "#2B5DAE", stroke = 2) +
  # Dual y-axes
  scale_y_continuous(
    name = "Number of Visits per Zone and Month",
    sec.axis = sec_axis(~ . / scale_factor, name = "Expected Number of Infested drains\nper Zone and Month")
  ) +
  scale_x_discrete(limits = x_levels, drop = FALSE,
                   labels = c(setNames(beta_levels, beta_levels), "ASPB" = "ASPB \n model")) +
  labs(x = expression(alpha)) +
  theme_minimal() +
  theme(
    axis.title.y.left  = element_text(size = 15, color = "#00BA38", margin = margin(r = 10)),
    axis.title.y.right = element_text(size = 15, color = "#619CFF", margin = margin(l = 10)),
    axis.text.y.left   = element_text(size = 12, color = "black"),
    axis.text.y.right  = element_text(size = 12, color = "black"),
    axis.title.x = element_blank(),
    axis.text.x  = element_blank(),
    panel.grid.minor   = element_blank(),
    panel.grid.major.x = element_blank()
  )

# Print median values of raw data for the top panel
cat("\n--- Top Panel Median Values ---\n")
median_summary <- box_data %>%
  group_by(x_value) %>%
  summarise(
    Median_Visits = median(Visits_month, na.rm = TRUE),
    Median_Risk_Original = median(Risk_zone_month, na.rm = TRUE),
    .groups = "drop"
  )
print(median_summary)

# --- Bottom panel: Cost decomposition (scissor plot) ---
# Norm_INT + Norm_PER = unweighted total cost. ASPB = 1 + 1 = 2.
# Two-stage mean: average across IDs within (Beta, Year) first → one value per
# year per alpha → then mean/SE across years. Each year contributes equally
# regardless of how many IDs survived the filter.
# SE reflects year-to-year variability (the dominant source); n = number of years.
# For the sum: SE_total = sqrt(SE_int^2 + SE_per^2) (propagation, assuming independence).

df_cost <- Results %>%
  distinct(ID, Year, Beta, Norm_INT, Norm_PER) %>%
  group_by(Beta, Year) %>%
  summarise(Norm_INT = mean(Norm_INT), Norm_PER = mean(Norm_PER), .groups = "drop") %>%
  group_by(Beta) %>%
  summarise(
    INT_mean = mean(Norm_INT),
    INT_se   = sd(Norm_INT) / sqrt(n()),
    PER_mean = mean(Norm_PER),
    PER_se   = sd(Norm_PER) / sqrt(n()),
    .groups = "drop"
  ) %>%
  mutate(
    Total_mean = INT_mean + PER_mean,
    Total_se   = sqrt(INT_se^2 + PER_se^2)
  )

# Pivot to long format
df_cost_long <- df_cost %>%
  select(Beta, INT_mean, INT_se, PER_mean, PER_se, Total_mean, Total_se) %>%
  pivot_longer(
    cols = -Beta,
    names_to = c("Variable", ".value"),
    names_pattern = "(INT|PER|Total)_(mean|se)"
  ) %>%
  mutate(
    Variable = recode(Variable,
                      "PER"   = "Intervention Cost",
                      "INT"   = "Mosquito Risk",
                      "Total" = "Total cost"),
    Variable = factor(Variable, levels = c("Intervention Cost",
                                           "Mosquito Risk",
                                           "Total cost")),
    x_value = factor(as.character(Beta), levels = x_levels)
  )

# Print normalized cost values from bottom panel
cat("\n--- Bottom Panel: Normalized Cost Values (mean ± SE) ---\n")
cost_summary <- df_cost_long %>%
  mutate(
    Alpha = Beta,
    Mean_SE = sprintf("%.4f ± %.4f", mean, se)
  ) %>%
  select(Alpha, Variable, Mean_SE) %>%
  pivot_wider(names_from = Variable, values_from = Mean_SE)
print(cost_summary)

var_colors <- c("Intervention Cost"      = "#00BA38",
                "Mosquito Risk"          = "#619CFF",
                "Total cost"             = "#F8766D")

p_scissor <- ggplot(df_cost_long, aes(x = x_value, y = mean, color = Variable,
                                       group = Variable)) +
  # Vertical separator between alpha values and ASPB (same position as top panel)
  geom_vline(xintercept = sep_x, linetype = "dotted", color = "grey60",
             linewidth = 0.5) +
  # ASPB reference: dashed lines with labels on the right (ASPB column)
  geom_hline(yintercept = 2.0, linetype = "dashed", color = "#F8766D",
             linewidth = 0.6, alpha = 0.5) +
  geom_hline(yintercept = 1.0, linetype = "dashed", color = "#30AB9B",
             linewidth = 0.4, alpha = 0.6) +
  # ASPB label annotations at the dashed lines
  annotate("text", x = length(x_levels), y = 2.0, label = "ASPB model",
           color = "#F8766D", size = 2.5, fontface = "bold", vjust = -0.5) +
  annotate("text", x = length(x_levels), y = 1.0, label = "ASPB model",
           color = "#30AB9B", size = 2.5, fontface = "bold", vjust = -0.5) +
  # Lines + points + error bars
  geom_line(linewidth = 0.9) +
  geom_errorbar(aes(ymin = mean - se, ymax = mean + se),
                width = 0.25, linewidth = 0.5, alpha = 0.7) +
  geom_point(size = 2.5) +
  # Use x_levels so both panels share the same axis; suppress "ASPB" tick label
  scale_x_discrete(limits = x_levels, drop = FALSE,
                   labels = c(setNames(beta_levels, beta_levels), "ASPB" = "ASPB\nmodel")) +
  scale_color_manual(values = var_colors, name = NULL) +
  labs(x = expression(alpha), y = "Normalised cost") +
  ylim(0, NA) +
  theme_minimal() +
  theme(
    legend.position = "bottom",
    legend.text = element_text(size = 13, color = "black"),
    axis.title.y = element_text(size = 15, color = "black", margin = margin(r = 10)),
    axis.title.x = element_text(size = 15, color = "black"),
    axis.text.x = element_text(size = 12, angle = 45, hjust = 1, color = "black"),
    axis.text.y = element_text(size = 12, color = "black"),
    plot.margin  = margin(t = 5, r = 5, b = 15, l = 5),
    panel.grid.minor   = element_blank(),
    panel.grid.major.x = element_blank()
  )

# Combine top + bottom panels
p_fig1_panel <- p_fig1 / p_scissor +
  plot_layout(heights = c(1, 0.8))

# Find alpha with minimum total cost
min_total_cost <- df_cost %>%
  mutate(Total_mean = INT_mean + PER_mean) %>%
  arrange(Total_mean) %>%
  slice(1)

cat("\n--- Minimum total cost ---\n")
cat(sprintf("  Alpha with lowest total cost: %.1f (Total = %.3f)\n",
            min_total_cost$Beta, min_total_cost$Total_mean))

save_and_display(p_fig1_panel, "Scissor_plot.pdf", w = 10, h = 10)
cat("Figure 1 saved.\n")


# =============================================================================
# 3. SCHEDULE ANALYSIS: which variable responds to alpha?
# =============================================================================

# =============================================================================

cat("\n========================================\n")
cat("3. SCHEDULE ANALYSIS: PERIODICITY vs START DAY\n")
cat("========================================\n\n")


sched_data <- Results %>%
  select(ID, Year, Beta, Zone, Periodicity, Init_times) %>%
  mutate(Zone_short = zone_short[Zone]) %>%
  group_by(Beta, Zone, Zone_short, Year) %>%
  summarise(
    Periodicity = mean(Periodicity),
    Init_times  = mean(Init_times),
    .groups = "drop"
  )

cat(sprintf("Schedule analysis dataset: %d cell-averaged rows (Beta x Zone x Year)\n", nrow(sched_data)))
cat(sprintf("  Periodicity range: %.0f – %.0f days\n",
            min(sched_data$Periodicity), max(sched_data$Periodicity)))
cat(sprintf("  Init_times range:  %.1f – %.1f (day of year)\n",
            min(sched_data$Init_times), max(sched_data$Init_times)))

# =========================================================================
# 3b. PER-ZONE SPEARMAN: does each variable track alpha within each zone?
# Each zone contributes 11 alpha x 6 year = 66 balanced data points.
# =========================================================================

cat("\n--- Per-zone Spearman rho(alpha, variable) ---\n")
cat(sprintf("%-18s %18s %18s   %s\n",
            "Zone", "rho(a, Period)", "rho(a, Init)", "Period monotone?"))

zone_alpha_corr <- sched_data %>%
  group_by(Zone_short) %>%
  summarise(
    rho_period = cor(Beta, Periodicity, method = "spearman"),
    rho_init   = cor(Beta, Init_times,  method = "spearman"),
    n = n(),
    .groups = "drop"
  ) %>%
  mutate(
    period_label = case_when(
      rho_period < -0.3 ~ "Yes (decreasing)",
      rho_period > +0.3 ~ "Yes (increasing)",
      TRUE ~ "No clear trend"
    )
  )

for (i in seq_len(nrow(zone_alpha_corr))) {
  r <- zone_alpha_corr[i, ]
  cat(sprintf("%-18s %+17.3f  %+17.3f   %s\n",
              r$Zone_short, r$rho_period, r$rho_init, r$period_label))
}

# =========================================================================
# 3c. SUMMARY
# =========================================================================

n_zones_period_monotone <- sum(abs(zone_alpha_corr$rho_period) > 0.3)
n_zones_init_monotone   <- sum(abs(zone_alpha_corr$rho_init) > 0.3)

avg_rho_period <- mean(zone_alpha_corr$rho_period)
avg_rho_init   <- mean(zone_alpha_corr$rho_init)

cat(sprintf("\n--- Summary ---\n"))
cat(sprintf("  Zones where periodicity tracks alpha (|rho| > 0.3): %d / %d\n",
            n_zones_period_monotone, nrow(zone_alpha_corr)))
cat(sprintf("  Zones where init_times tracks alpha (|rho| > 0.3):  %d / %d\n",
            n_zones_init_monotone, nrow(zone_alpha_corr)))
cat(sprintf("  Average rho(alpha, Periodicity):  %+.3f\n", avg_rho_period))
cat(sprintf("  Average rho(alpha, Init_times):   %+.3f\n", avg_rho_init))
cat(sprintf("  Periodicity responds systematically; start day does not.\n"))
cat("  -> Treatment frequency is the dominant scheduling variable.\n\n")


# =============================================================================
# 3d. KRUSKAL-WALLIS: does periodicity differ across zones? across years?
# =============================================================================

cat("\n========================================\n")
cat("3d. KRUSKAL-WALLIS TESTS (alpha =", alpha_best, ")\n")
cat("========================================\n\n")

kw_data <- sched_data %>% filter(Beta == alpha_best)

cat(sprintf("KW dataset: %d rows (7 zones × 6 years)\n\n", nrow(kw_data)))

# --- Periodicity across zones (pooling years) ---
kw_period_zones <- kruskal.test(Periodicity ~ Zone_short, data = kw_data)
cat(sprintf("Periodicity across ZONES:  H = %.2f, df = %d, p = %.4f  %s\n",
            kw_period_zones$statistic, kw_period_zones$parameter,
            kw_period_zones$p.value,
            ifelse(kw_period_zones$p.value < 0.05, "***", "n.s.")))

# --- Periodicity across years (pooling zones) ---
kw_period_years <- kruskal.test(Periodicity ~ factor(Year), data = kw_data)
cat(sprintf("Periodicity across YEARS:  H = %.2f, df = %d, p = %.4f  %s\n",
            kw_period_years$statistic, kw_period_years$parameter,
            kw_period_years$p.value,
            ifelse(kw_period_years$p.value < 0.05, "***", "n.s.")))

# --- Init_times across zones (pooling years) ---
kw_init_zones <- kruskal.test(Init_times ~ Zone_short, data = kw_data)
cat(sprintf("Init_times across ZONES:   H = %.2f, df = %d, p = %.4f  %s\n",
            kw_init_zones$statistic, kw_init_zones$parameter,
            kw_init_zones$p.value,
            ifelse(kw_init_zones$p.value < 0.05, "***", "n.s.")))

# --- Init_times across years (pooling zones) ---
kw_init_years <- kruskal.test(Init_times ~ factor(Year), data = kw_data)
cat(sprintf("Init_times across YEARS:   H = %.2f, df = %d, p = %.4f  %s\n",
            kw_init_years$statistic, kw_init_years$parameter,
            kw_init_years$p.value,
            ifelse(kw_init_years$p.value < 0.05, "***", "n.s.")))

cat("\n--- Interpretation ---\n")
cat("  If periodicity differs across zones but not years: zone structure\n")
cat("  matters more than interannual climate variability.\n")
cat("  If init_times shows no significance: start day is noise.\n\n")

# Per-zone medians for context
cat("--- Per-zone median periodicity (alpha =", alpha_best, ") ---\n")
zone_medians <- kw_data %>%
  group_by(Zone_short) %>%
  summarise(Median_Period = median(Periodicity),
            IQR_Period = IQR(Periodicity), .groups = "drop") %>%
  arrange(Median_Period)
for (i in seq_len(nrow(zone_medians))) {
  r <- zone_medians[i, ]
  cat(sprintf("  %-18s  median = %5.1f days  (IQR = %.1f)\n",
              r$Zone_short, r$Median_Period, r$IQR_Period))
}
cat("\n")


# =============================================================================
# 4. COMBINED HEATMAP: ΔVisits AND Extra risk reduction vs ASPB
# =============================================================================
# Horizontal table-heatmap with:
#   Columns = 7 zones + "City" (mean across zones)
#   Rows    = two metrics:
#     - ΔVisits/zone/month  (opt − ASPB, same as heatmap Mean column)
#     - Extra risk reduction (pp) = (ASPB_Zone_INT − Opt_Zone_INT) / Untreated_Zone_INT × 100
#       Positive = optimizer reduces risk MORE than ASPB
#   Three stacked panels: alpha_min (top), alpha_best (middle), alpha_even (bottom).
#   alpha_min = 0.1 is the mirror case to alpha_even = 0.8: minimal visits with
#   risk just dipping below ASPB.
#
# The "Extra risk reduction" metric is comparable across zones because we
# normalize by the untreated risk of each zone-year (unlike raw Zone_INT which
# varies by orders of magnitude: ~30 for Teatre Grec vs ~4000 for Putxet).
# =============================================================================

cat("\n========================================\n")
cat("4. COMBINED HEATMAP: VISITS + RISK vs ASPB\n")
cat("========================================\n\n")

# --- Build zone-year level data for all three alphas ---
opt_zy <- Results %>%
  filter(Beta %in% c(alpha_min, alpha_best, alpha_even)) %>%
  group_by(Beta, Zone, Year) %>%
  summarise(Zone_INT_opt = mean(Zone_INT, na.rm = TRUE),
            Zone_Visits_opt = mean(Zone_Visits, na.rm = TRUE),
            .groups = "drop")

aspb_zy <- ASPB_simulations %>%
  select(Zone, Year, Zone_INT, Zone_Visits) %>%
  rename(Zone_INT_aspb = Zone_INT, Zone_Visits_aspb = Zone_Visits)

untrt_zy <- Untreated_simulations %>%
  select(Zone, Year, Zone_INT) %>%
  rename(Zone_INT_untrt = Zone_INT)

combined_zy <- opt_zy %>%
  left_join(aspb_zy, by = c("Zone", "Year")) %>%
  left_join(untrt_zy, by = c("Zone", "Year")) %>%
  mutate(
    Zone_short = zone_short[Zone],
    Delta_Visits = (Zone_Visits_opt - Zone_Visits_aspb) / SEASON_DAYS * 30,
    Extra_Risk_Red = (Zone_INT_opt - Zone_INT_aspb) / Zone_INT_untrt * 100
  )

# Per-zone means (across years)
zone_means <- combined_zy %>%
  group_by(Beta, Zone_short) %>%
  summarise(Delta_Visits = mean(Delta_Visits),
            Extra_Risk_Red = mean(Extra_Risk_Red),
            .groups = "drop")

# City totals (sum across zones).
# Delta_Visits: sum of per-zone deltas = total city visits/month change.
# Extra_Risk_Red: city-level ratio using summed numerators/denominators,
#   NOT the mean of per-zone ratios (which would mix incompatible denominators).
city_totals_raw <- combined_zy %>%
  group_by(Beta, Year) %>%
  summarise(
    sum_opt    = sum(Zone_INT_opt),
    sum_aspb   = sum(Zone_INT_aspb),
    sum_untrt  = sum(Zone_INT_untrt),
    sum_dv     = sum(Delta_Visits),
    .groups = "drop"
  ) %>%
  mutate(
    Delta_Visits   = sum_dv,
    Extra_Risk_Red = (sum_opt - sum_aspb) / sum_untrt * 100
  )

city_means <- city_totals_raw %>%
  group_by(Beta) %>%
  summarise(Delta_Visits   = mean(Delta_Visits),
            Extra_Risk_Red = mean(Extra_Risk_Red),
            .groups = "drop") %>%
  mutate(Zone_short = "Total")

# Print summary
cat("--- Per-zone means (across years) ---\n")
cat(sprintf("%-18s  %-5s  %12s  %12s\n", "Zone", "Alpha", "dVisits/mo", "Extra Risk pp"))
for (i in seq_len(nrow(zone_means))) {
  r <- zone_means[i, ]
  cat(sprintf("%-18s  a=%.1f  %+11.2f  %+11.1f\n",
              r$Zone_short, r$Beta, r$Delta_Visits, r$Extra_Risk_Red))
}
for (i in seq_len(nrow(city_means))) {
  r <- city_means[i, ]
  cat(sprintf("%-18s  a=%.1f  %+11.2f  %+11.1f\n",
              r$Zone_short, r$Beta, r$Delta_Visits, r$Extra_Risk_Red))
}

# Pivot to long format for heatmap
heat_combined <- bind_rows(zone_means, city_means) %>%
  pivot_longer(cols = c(Delta_Visits, Extra_Risk_Red),
               names_to = "Metric", values_to = "Value") %>%
  mutate(
    Metric_label = recode(Metric,
                          "Delta_Visits"   = "∆ Visits/month",
                          "Extra_Risk_Red" = "∆ Risk (pp)"),
    Metric_label = factor(Metric_label,
                          levels = c("∆ Risk (pp)", "∆ Visits/month"))
  )

# Zone order: zones first, Total last
zone_col_levels <- c(as.character(zone_short), "Total")
heat_combined <- heat_combined %>%
  mutate(Zone_short = factor(Zone_short, levels = zone_col_levels))

# Symmetric limits across both panels (shared per metric)
max_abs_v <- max(abs(heat_combined$Value[heat_combined$Metric == "Delta_Visits"]))
max_abs_r <- max(abs(heat_combined$Value[heat_combined$Metric == "Extra_Risk_Red"]))

# Build ONE combined heatmap with facet_grid.

heat_plot_data <- heat_combined %>%
  filter(Beta %in% c(alpha_min, alpha_best, alpha_even)) %>%
  mutate(
    label = ifelse(Metric == "Delta_Visits",
                   sprintf("%+.2f", Value),
                   sprintf("%+.1f", Value)),
    Value_scaled = case_when(
      Metric == "Delta_Visits"   ~ Value / max_abs_v,
      Metric == "Extra_Risk_Red" ~ Value / max_abs_r
    ),
    # Parsed label: use tilde-space around '=' to avoid clipping of == in strip
    alpha_label = factor(
      paste0("alpha~~'='~", sprintf("%.1f", Beta)),
      levels = paste0("alpha~~'='~", sprintf("%.1f",
                      sort(c(alpha_min, alpha_best, alpha_even))))
    )
  )

p_combined_heat <- ggplot(heat_plot_data,
                           aes(x = Zone_short, y = Metric_label, fill = Value_scaled)) +
  geom_tile(color = "white", linewidth = 0.8) +
