  # #4393C3: mid-tone ColorBrewer RdBu blue — lighter than #2166AC for readability
  scale_fill_gradient2(low = "#4393C3", mid = "white", high = "#B2182B",
                       midpoint = 0, limits = c(-1, 1), guide = "none") +
  facet_grid(alpha_label ~ ., labeller = label_parsed, switch = "y",
