  scale_x_discrete() +
  scale_y_discrete() +
  labs(x = NULL, y = NULL,
       caption = paste0(
         "\u0394 Visits/month := Visits/month(\u03b1) \u2212 Visits/month(ASPB)\n",
         "\u0394 Risk (pp) := pp of Mosquito Risk reduction (ASPB) \u2212 ",
         "pp of Mosquito Risk reduction (\u03b1)")) +
  theme_minimal() +
  theme(
    axis.text.x         = element_text(size = 13, angle = 30, hjust = 1,
                                        color = "black"),
    axis.ticks.x        = element_blank(),
    axis.text.y         = element_text(size = 13, color = "black"),
    strip.text.y.left   = element_text(size = 18, face = "bold", color = "black",
                                        angle = 90, margin = margin(r = 12)),
    strip.placement     = "outside",
    strip.background    = element_blank(),
    panel.spacing       = unit(0.5, "lines"),
    panel.grid          = element_blank(),
    plot.caption        = element_text(size = 14, color = "black", hjust = 0.5,
                                        margin = margin(t = 12))
  )

save_and_display(p_combined_heat, "Risk_Effort_ASPB_Opt_Differences.pdf", w = 12, h = 9)
save_and_display(p_combined_heat, "Risk_Effort_ASPB_Opt_Differences.pdf", w = 12, h = 9)
cat("Combined visits+risk heatmap saved.\n")


# =============================================================================
# 5. LOLLIPOP: partial Spearman correlations (two-panel)
# =============================================================================
# Two-panel figure, both with n = 42 (7 zones × 6 years), 6 predictors × 3 outputs.
#
# Panel A — partial | Year (removes year-level shifts, isolates cross-zone signal).
#   Structural predictors (drains, distance) are interpretable here.
#   Climate predictors may show collinearity artifacts (e.g., temperature as
#   proxy for zone identity) — shown for completeness.
#
# Panel B — partial | Zone (removes zone identity, isolates cross-year signal).
#   Climate predictors are interpretable here.
#   Structural predictors may be noisy (drain count varies with reform campaigns).
#
# Method: rank-residualization. Rank all 42 values, subtract within-group rank
# means, compute Pearson r on residuals. Equivalent to partial Spearman.
# df = 42 − 6 = 36 (partial|Year) or 42 − 7 = 35 (partial|Zone).
# =============================================================================

cat("\n========================================\n")
cat("5. DRIVERS: VARIANCE DECOMPOSITION + PARTIAL CORRELATIONS\n")
cat("========================================\n\n")

# --- Zone×year summary at alpha_best ---
zy_summary <- Results %>%
  filter(Beta == alpha_best) %>%
  group_by(Zone, Year) %>%
  summarise(
    Mean_Zone_INT    = mean(Zone_INT, na.rm = TRUE),
    Mean_Zone_Visits = mean(Zone_Visits, na.rm = TRUE),
    .groups = "drop"
  ) %>%
  left_join(predictors, by = c("Zone", "Year")) %>%
  mutate(
    Risk_reduction_pp   = (1 - Mean_Zone_INT / Zone_INT_Untreated) * 100,
    Reduction_per_visit = Risk_reduction_pp / Mean_Zone_Visits
  )

cat(sprintf("n = %d (zone x year)\n", nrow(zy_summary)))

# ==========================================================================
# Helpers
# ==========================================================================
partial_spearman <- function(x, y, groups) {
  rx <- rank(x)
  ry <- rank(y)
  for (g in unique(groups)) {
    m <- groups == g
    rx[m] <- rx[m] - mean(rx[m])
    ry[m] <- ry[m] - mean(ry[m])
  }
  test <- cor.test(rx, ry, method = "pearson")
  c(rho = unname(test$estimate), pval = test$p.value)
}

eta_sq_ranks <- function(values, groups) {
  r <- rank(values)
  grand <- mean(r)
  ss_total <- sum((r - grand)^2)
  if (ss_total == 0) return(0)
  group_means <- ave(r, groups, FUN = mean)
  ss_group <- sum((group_means - grand)^2)
  ss_group / ss_total
}

# ==========================================================================
# PANEL: Partial Spearman lollipop (mixed-partial)
# ==========================================================================

cat("\n--- Partial Spearman correlations ---\n")

# Structural predictors: partial|Year (isolates cross-zone signal)
struct_preds <- list(
  list(col = "N_active_drains", label = "Number of water drains",      ctrl = "Year"),
  list(col = "Mean_Intra_Dist", label = "Mean inter-drain distance", ctrl = "Year")
)

# Climate predictors: partial|Zone (isolates cross-year signal)
climate_preds <- list(
  list(col = "Mean_Temperature",  label = "Mean temperature",                ctrl = "Zone"),
  list(col = "Dry_days_frac",     label = "Fraction of dry days",            ctrl = "Zone"),
  list(col = "N_flush_events",    label = "Flushing events",                 ctrl = "Zone")
)

all_preds <- c(struct_preds, climate_preds)

output_cols <- list(
  list(col = "Zone_INT_Untreated",  label = "Baseline MR"),
  list(col = "Mean_Zone_Visits",    label = "Number of visits"),
  list(col = "Reduction_per_visit", label = "MR reduction per visit")
)

loll_rows <- list()
for (pred in all_preds) {
  ctrl_vec <- if (pred$ctrl == "Year") zy_summary$Year else zy_summary$Zone
  for (out in output_cols) {
    res <- partial_spearman(zy_summary[[pred$col]], zy_summary[[out$col]], ctrl_vec)
    sig <- ifelse(res["pval"] < 0.01, "**", ifelse(res["pval"] < 0.05, "*", ""))
    cat(sprintf("  %-30s |%-6s  %-25s  %+.3f  %.4f %s\n",
                pred$label, pred$ctrl, out$label, res["rho"], res["pval"], sig))
    loll_rows <- c(loll_rows, list(data.frame(
      predictor  = pred$label,
      output     = out$label,
      rho        = res["rho"],
      pval       = res["pval"],
      sig_label  = paste0(sprintf("%+.2f", res["rho"]), sig),
      pred_group = ifelse(pred$ctrl == "Year",
                          "Structural",
                          "Climatic"),
      stringsAsFactors = FALSE
    )))
  }
}

loll_df <- bind_rows(loll_rows)

# Factor ordering
pred_order <- rev(sapply(all_preds, `[[`, "label"))
loll_df$predictor <- factor(loll_df$predictor, levels = pred_order)
loll_df$pred_group <- factor(loll_df$pred_group,
                             levels = c("Structural",
                                        "Climatic"))

dodge_levels <- c("Number of visits", "MR reduction per visit", "Baseline MR")
loll_df$output <- factor(loll_df$output, levels = dodge_levels)

output_shapes <- c("Baseline MR" = 16,
                   "MR reduction per visit" = 18,
                   "Number of visits" = 17)
dodge_w <- 0.55

p_drivers <- ggplot(loll_df, aes(x = rho, y = predictor, shape = output, group = output)) +
  facet_grid(pred_group ~ ., scales = "free_y", space = "free_y") +
  geom_vline(xintercept = 0, linetype = "dashed", color = "grey50", linewidth = 0.5) +
  geom_linerange(aes(xmin = 0, xmax = rho),
                 linewidth = 1.0, alpha = 0.8,
                 position = position_dodge(width = dodge_w),
                 color = "#B2182B",
                 show.legend = FALSE) +
  geom_point(size = 4,
             position = position_dodge(width = dodge_w),
             color = "#B2182B",
             show.legend = TRUE) +
  geom_text(aes(label = sig_label,
                hjust = ifelse(rho >= 0, -0.35, 1.35)),
            position = position_dodge(width = dodge_w),
            size = 4.0, fontface = "bold", show.legend = FALSE) +
  scale_shape_manual(values = output_shapes, name = NULL) +
  scale_x_continuous(limits = c(-1.15, 1.15), breaks = seq(-1, 1, 0.5)) +
  guides(shape = guide_legend(override.aes = list(color = "black", size = 3.5),
                              reverse = TRUE)) +
  labs(x = expression(paste("Spearman ", rho)), 
       y = NULL) +
  theme_minimal(base_size = 12) +
  theme(
    legend.position    = "bottom",
    legend.text        = element_text(size = 13, color = "black"),
    strip.text.y       = element_text(size = 14, angle = -90, color = "black"),
    axis.text.y        = element_text(size = 14, color = "black"),
    axis.text.x        = element_text(size = 10, color = "black"),
    axis.title.x       = element_text(size = 16, margin = margin(t = 10), color = "black"),
    panel.grid.major.y = element_blank(),
    panel.grid.minor   = element_blank()
  )

save_and_display(p_drivers, "Drivers_Lollipop.pdf", w = 10, h = 7)
cat("Drivers lollipop figure saved.\n")


